class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>> res = new LinkedList<>();
        LinkedList<Integer> stack = new LinkedList<>();
        combinationSum(candidates, target, stack, 0, res);
        return res;
    }

    public void combinationSum(int[] candidates, int target, LinkedList<Integer> stack, int index,  List<List<Integer>> res) {
        if(index==candidates.length) return;
        if(target == 0){
            List<Integer> temp = new LinkedList<>(stack);
            res.add(temp);
        }else if(candidates[index] > target){
            combinationSum(candidates, target, stack, index+1, res);
        }else{
            stack.push(candidates[index]);
            combinationSum(candidates, target - candidates[index], stack, index, res);
            stack.pop();
            combinationSum(candidates, target, stack, index+1, res);
        }
    }
}
